/*
 * Bitlight core — the look, in one place.
 *
 * Everything that decides how a Bitlight pixel looks lives here and only here:
 * the lamp model, the tone curve, the soft shadow, the 8×8 Bayer order and the
 * paper halo. The interactive kernel (bitlight.js) and the film engine
 * (film/engine.mjs) both call these functions, so a figure on a web page and a
 * shot in a film can never drift apart.
 *
 * No DOM here. Runs in browsers, workers and Node.
 */

// ---------- tone ----------
// AMBIENT: fill light on every surface (scenes may override; night shots use 0)
// POWER, FALLOFF: lamp brightness and distance falloff, atten = POWER / (1 + FALLOFF·d²)
// GAMMA: <1 lifts mid-tones so area coverage of dots reads like the intended grey
export const LOOK = Object.freeze({ AMBIENT: 0.035, POWER: 2.4, FALLOFF: 0.32, GAMMA: 0.72, HALO_DEPTH: 0.12 });

// ---------- ordered dither ----------
// 8×8 Bayer thresholds in (0, 1). Ordered, never error-diffused: diffusion makes
// every dot swim when the light moves (rules · 04 Order).
export const BAYER = (() => {
  let m = [[0, 2], [3, 1]];
  while (m.length < 8) {
    const n = m.length, next = [];
    for (let y = 0; y < 2 * n; y++) {
      next.push([]);
      for (let x = 0; x < 2 * n; x++) {
        const q = [0, 2, 3, 1][(y >= n ? 2 : 0) + (x >= n ? 1 : 0)];
        next[y].push(4 * m[y % n][x % n] + q);
      }
    }
    m = next;
  }
  return Float32Array.from(m.flat(), (v) => (v + 0.5) / 64);
})();

// ---------- screens ----------
// Other ordered threshold maps, all 8×8 and tiled: a "screen" is only the order
// in which dots switch on as light rises. Every one is fixed in the page, so the
// shading still holds while the lamp moves (rules · 04 Order). Error diffusion is
// not offered and never will be.
export const SCREENS = (() => {
  const rank = (score) => {
    const idx = [...score.keys()].sort((a, b) => score[a] - score[b] || a - b);
    const out = new Float32Array(64);
    idx.forEach((k, i) => { out[k] = (i + 0.5) / 64; });
    return out;
  };
  const cells = (fn) => Array.from({ length: 64 }, (_, k) => fn(k & 7, k >> 3));
  const b4 = Float32Array.from(cells((x, y) => {
    const m = [[0, 8, 2, 10], [12, 4, 14, 6], [3, 11, 1, 9], [15, 7, 13, 5]];
    return (m[y & 3][x & 3] + 0.5) / 16;
  }));
  let seed = 7; // fixed seed: the same grain on every machine
  const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296);
  return Object.freeze({
    bayer: BAYER,
    bayer4: b4,
    // clustered dots: a lit dot grows from the middle of each 4×4 cell
    dots: rank(cells((x, y) => (((x & 3) - 1.5) ** 2 + ((y & 3) - 1.5) ** 2) + BAYER[y * 8 + x] * 0.01)),
    // horizontal and 45° line screens
    lines: rank(cells((x, y) => Math.abs((y & 3) - 1.5) + BAYER[y * 8 + x] * 0.5)),
    diagonal: rank(cells((x, y) => Math.abs(((x + y) & 3) - 1.5) + BAYER[y * 8 + x] * 0.5)),
    // fixed grain
    noise: rank(cells(() => rnd())),
  });
})();

// ---------- signed distance helpers ----------
const sqrt = Math.sqrt, abs = Math.abs, max = Math.max, min = Math.min;
export const sd = {
  sphere(x, y, z, r) { return sqrt(x * x + y * y + z * z) - r; },
  // box with half-sizes bx, by, bz and edge radius r
  box(x, y, z, bx, by, bz, r = 0) {
    const qx = abs(x) - bx + r, qy = abs(y) - by + r, qz = abs(z) - bz + r;
    const ox = max(qx, 0), oy = max(qy, 0), oz = max(qz, 0);
    return sqrt(ox * ox + oy * oy + oz * oz) + min(max(qx, max(qy, qz)), 0) - r;
  },
  // ring lying in the xz plane
  torus(x, y, z, R, r) { const q = sqrt(x * x + z * z) - R; return sqrt(q * q + y * y) - r; },
  // vertical cylinder centred on the origin, half-height h, edge radius e
  cylinder(x, y, z, r, h, e = 0) {
    const dx = sqrt(x * x + z * z) - r + e, dy = abs(y) - h + e;
    const ox = max(dx, 0), oy = max(dy, 0);
    return min(max(dx, dy), 0) + sqrt(ox * ox + oy * oy) - e;
  },
  capsule(x, y, z, ax, ay, az, bx, by, bz, r) {
    const px = x - ax, py = y - ay, pz = z - az, dx = bx - ax, dy = by - ay, dz = bz - az;
    const h = max(0, min(1, (px * dx + py * dy + pz * dz) / (dx * dx + dy * dy + dz * dz)));
    const ex = px - dx * h, ey = py - dy * h, ez = pz - dz * h;
    return sqrt(ex * ex + ey * ey + ez * ez) - r;
  },
  // 2D box in any plane: half-sizes bx, by
  rect(x, y, bx, by) {
    const qx = abs(x) - bx, qy = abs(y) - by;
    return sqrt(max(qx, 0) ** 2 + max(qy, 0) ** 2) + min(max(qx, qy), 0);
  },
  // solid of revolution around the y axis from a 2D profile distance f(r, y)
  revolve(x, y, z, f) { return f(sqrt(x * x + z * z), y); },
  smin(a, b, k) { const h = max(k - abs(a - b), 0) / k; return min(a, b) - h * h * k * 0.25; },
};

// ---------- shadow ----------
// Soft shadow toward a light. `occ` is everything that can cast shadow (never the
// floor or plate: a convex ground cannot shade itself). `bound` = [x, y, z, r]
// optional sphere around all casters; rays that miss it are fully lit.
export function softShadow(occ, x, y, z, lx, ly, lz, dist, bound) {
  if (bound) {
    const ocx = x - bound[0], ocy = y - bound[1], ocz = z - bound[2];
    const b = ocx * lx + ocy * ly + ocz * lz;
    const c = ocx * ocx + ocy * ocy + ocz * ocz - bound[3] * bound[3];
    if (c > 0 && (b > 0 || b * b - c < 0)) return 1;
  }
  let res = 1, t = 0.015;
  for (let s = 0; s < 56 && t < dist; s++) {
    const h = occ(x + lx * t, y + ly * t, z + lz * t);
    if (h < 0.001) return 0;
    res = min(res, (9 * h) / t);
    if (res < 0.01) return 0;
    t += max(0.01, h);
  }
  return max(0, min(1, res));
}

// ---------- surface ----------
// Ambient occlusion from five taps along the normal. Light-independent.
export function occlusion(map, x, y, z, nx, ny, nz) {
  let ao = 0, w = 1;
  for (let s = 1; s <= 5; s++) {
    const h = 0.04 * s;
    ao += w * (h - map(x + nx * h, y + ny * h, z + nz * h));
    w *= 0.6;
  }
  return max(0, min(1, 1 - 3.2 * ao));
}

// Normal by the tetrahedron technique; writes into `n` ([x, y, z]).
export function normal(map, x, y, z, n, e = 0.0013) {
  const a = map(x + e, y - e, z - e), b = map(x - e, y - e, z + e);
  const c = map(x - e, y + e, z - e), g = map(x + e, y + e, z + e);
  let gx = a - b - c + g, gy = -a - b + c + g, gz = -a + b - c + g;
  const l = sqrt(gx * gx + gy * gy + gz * gz) || 1;
  n[0] = gx / l; n[1] = gy / l; n[2] = gz / l;
}

/**
 * Display brightness of one surface point, 0 = ink, ≥1 = paper.
 *   mat     { a: albedo 0–1, s: specular 0|1, e: emission 0–1 }
 *   lights  [{ p: [x, y, z], power?, falloff?, spot?: { dir: [x, y, z], inner, outer } }]
 *   view    [x, y, z] direction the camera looks (orthographic)
 */
export function shade(x, y, z, nx, ny, nz, ao, mat, lights, amb, view, occ, bound, gamma = LOOK.GAMMA) {
  let L = amb * ao;
  for (let i = 0; i < lights.length; i++) {
    const lt = lights[i];
    let lx = lt.p[0] - x, ly = lt.p[1] - y, lz = lt.p[2] - z;
    const dist = sqrt(lx * lx + ly * ly + lz * lz);
    lx /= dist; ly /= dist; lz /= dist;
    const ndl = nx * lx + ny * ly + nz * lz;
    if (ndl <= 0) continue;
    let cone = 1;
    if (lt.spot) {
      const sp = lt.spot, cd = -(lx * sp.dir[0] + ly * sp.dir[1] + lz * sp.dir[2]);
      cone = max(0, min(1, (cd - sp.outer) / (sp.inner - sp.outer)));
      cone = cone * cone * (3 - 2 * cone);
      if (cone <= 0) continue;
    }
    const sh = softShadow(occ, x + nx * 0.004, y + ny * 0.004, z + nz * 0.004, lx, ly, lz, dist, bound);
    if (sh <= 0) continue;
    const atten = (lt.power ?? LOOK.POWER) / (1 + (lt.falloff ?? LOOK.FALLOFF) * dist * dist);
    L += ndl * sh * cone * atten * (0.55 + 0.45 * ao);
    if (mat.s) {
      let hx = lx - view[0], hy = ly - view[1], hz = lz - view[2];
      const hl = sqrt(hx * hx + hy * hy + hz * hz);
      const ndh = (nx * hx + ny * hy + nz * hz) / hl;
      if (ndh > 0) L += sh * cone * Math.pow(ndh, 60) * 0.9;
    }
  }
  L = Math.pow(L * mat.a, gamma);
  return mat.e > L ? mat.e : L;
}

/**
 * Order a W×H brightness field into bits (1 = lit, 0 = unlit).
 *   lum    brightness per cell; < 0 marks a miss (paints `ground`)
 *   depth  ray distance per cell, for the halo
 * A hit cell just behind a nearer neighbour is lit — the paper halo (rules · 05).
 * `haloLight` > 0 draws it only where either side is at least that bright: films
 * use 0.12 so darkness keeps its secrets; figures use 0 so a dark object never
 * melts into its own dark shadow.
 * (x0, y0) offsets the screen phase so tiles of one frame line up. `screen` is an
 * 8×8 threshold map (default Bayer; see SCREENS).
 */
export function dither(lum, depth, W, H, bits, stride, x0, y0, ground, haloLight = 0, screen = BAYER) {
  const D = LOOK.HALO_DEPTH, HL = haloLight;
  for (let j = 0, k = 0; j < H; j++) {
    const row = ((y0 + j) & 7) * 8, out = (y0 + j) * stride + x0;
    for (let i = 0; i < W; i++, k++) {
      const L = lum[k];
      if (L < 0) { bits[out + i] = ground; continue; }
      const d = depth[k];
      let near = -1;
      if (i > 0 && d - depth[k - 1] > D) near = max(near, lum[k - 1]);
      if (i < W - 1 && d - depth[k + 1] > D) near = max(near, lum[k + 1]);
      if (j > 0 && d - depth[k - W] > D) near = max(near, lum[k - W]);
      if (j < H - 1 && d - depth[k + W] > D) near = max(near, lum[k + W]);
      const halo = near > -1 && (HL <= 0 || max(near, L) > HL);
      bits[out + i] = halo || L > screen[row + ((x0 + i) & 7)] ? 1 : 0;
    }
  }
}

/**
 * The same ordering for more than two inks. `levels` = number of tones (2–16);
 * each cell lands on one of 0 … levels−1, dithered between its two nearest tones
 * with the same fixed screen, so shading still holds still. Misses paint `ground`
 * (a level, 0 or levels−1). The halo paints the top level.
 */
export function ditherLevels(lum, depth, W, H, out, stride, x0, y0, ground, haloLight = 0, screen = BAYER, levels = 4) {
  const D = LOOK.HALO_DEPTH, HL = haloLight, top = levels - 1;
  for (let j = 0, k = 0; j < H; j++) {
    const row = ((y0 + j) & 7) * 8, o = (y0 + j) * stride + x0;
    for (let i = 0; i < W; i++, k++) {
      const L = lum[k];
      if (L < 0) { out[o + i] = ground; continue; }
      const d = depth ? depth[k] : 0;
      let near = -1;
      if (depth) {
        if (i > 0 && d - depth[k - 1] > D) near = max(near, lum[k - 1]);
        if (i < W - 1 && d - depth[k + 1] > D) near = max(near, lum[k + 1]);
        if (j > 0 && d - depth[k - W] > D) near = max(near, lum[k - W]);
        if (j < H - 1 && d - depth[k + W] > D) near = max(near, lum[k + W]);
      }
      if (near > -1 && (HL <= 0 || max(near, L) > HL)) { out[o + i] = top; continue; }
      const v = (L < 0 ? 0 : L > 1 ? 1 : L) * top, base = Math.floor(v);
      out[o + i] = min(top, base + (v - base > screen[row + ((x0 + i) & 7)] ? 1 : 0));
    }
  }
}

/** `levels` colours stepping from `unlit` to `lit` ([r, g, b] 0–255 each). */
export function ramp(unlit, lit, levels) {
  return Array.from({ length: levels }, (_, i) => unlit.map((u, c) => Math.round(u + (lit[c] - u) * (i / (levels - 1)))));
}

// ---------- camera ----------
// Orthographic camera: yaw/pitch in degrees, `half` = half the visible width in
// world units. Returns the ray basis used by both engines.
export function camera(yawDeg, pitchDeg) {
  const yaw = (yawDeg * Math.PI) / 180, pitch = (pitchDeg * Math.PI) / 180;
  const f = [-Math.cos(pitch) * Math.sin(yaw), -Math.sin(pitch), -Math.cos(pitch) * Math.cos(yaw)];
  const r = [Math.cos(yaw), 0, -Math.sin(yaw)];
  const u = [-r[2] * f[1], r[2] * f[0] - r[0] * f[2], r[0] * f[1]];
  return { f, r, u };
}

// March one ray. Returns distance travelled, or -1 for a miss.
export function march(map, ox, oy, oz, fx, fy, fz, maxT = 60, steps = 180) {
  let t = 0;
  for (let s = 0; s < steps && t < maxT; s++) {
    const d = map(ox + fx * t, oy + fy * t, oz + fz * t);
    if (d < 0.0007) return t;
    t += d;
  }
  return -1;
}

// Lamp read-out shared by figures and films: "az 214° · el 38°"
export function lampAngles(p, target = [0, 0, 0]) {
  const x = p[0] - target[0], y = p[1] - target[1], z = p[2] - target[2];
  const az = ((Math.atan2(z, x) * 180) / Math.PI + 360) % 360;
  const el = (Math.atan2(y, Math.hypot(x, z)) * 180) / Math.PI;
  return { az: Math.round(az), el: Math.round(el) };
}

/*
 * Bitlight image — the same look for photographs and video frames.
 *
 * A picture becomes a brightness field (0–1), is tuned (levels, contrast,
 * sharpen), shrunk to a grid of cells, and ordered into inks with the same
 * screens the figures use (core.SCREENS). No DOM and no decoding here: callers
 * hand in RGBA or gray bytes, so it runs in the browser, in Node and in workers.
 *
 *   const lum = lumaFromRGBA(rgba, w, h);
 *   const grid = toGrid(lum, w, h, cols);              // { lum, W, H }
 *   tune(grid.lum, grid.W, grid.H, { auto: true, contrast: 1.1, sharpen: 0.6 });
 *   const levels = dither(grid.lum, grid.W, grid.H, { screen: "bayer", tones: 2 });
 *   // levels[k] is 0 … tones−1; colour them with core.ramp()
 */
import { SCREENS, ditherLevels, ramp } from "./core.js";

export { SCREENS, ramp };

/** Rec. 709 luma of RGBA bytes, 0–1. Transparent pixels count as paper. */
export function lumaFromRGBA(rgba, w, h) {
  const out = new Float32Array(w * h);
  for (let i = 0, k = 0; k < out.length; i += 4, k++) {
    const a = rgba[i + 3] / 255, y = (0.2126 * rgba[i] + 0.7152 * rgba[i + 1] + 0.0722 * rgba[i + 2]) / 255;
    out[k] = y * a + (1 - a);
  }
  return out;
}

/** Area-average a w×h field down to `cols` cells wide (rows follow the aspect, or pass `rows`). */
export function toGrid(lum, w, h, cols, rows = Math.max(1, Math.round((cols * h) / w))) {
  const out = new Float32Array(cols * rows);
  for (let j = 0; j < rows; j++) {
    const y0 = (j * h) / rows, y1 = ((j + 1) * h) / rows;
    for (let i = 0; i < cols; i++) {
      const x0 = (i * w) / cols, x1 = ((i + 1) * w) / cols;
      let sum = 0, wt = 0;
      for (let y = Math.floor(y0); y < Math.ceil(y1); y++) {
        const wy = Math.min(y + 1, y1) - Math.max(y, y0);
        for (let x = Math.floor(x0); x < Math.ceil(x1); x++) {
          const wx = Math.min(x + 1, x1) - Math.max(x, x0), f = wx * wy;
          sum += lum[Math.min(h - 1, y) * w + Math.min(w - 1, x)] * f; wt += f;
        }
      }
      out[j * cols + i] = wt ? sum / wt : 0;
    }
  }
  return { lum: out, W: cols, H: rows };
}

/** The 1st and 99th percentile of a field, as 0–255. Video passes a smoothed pair as `range`. */
export function levelsOf(lum) {
  const n = lum.length, hist = new Uint32Array(256);
  for (let k = 0; k < n; k++) hist[Math.max(0, Math.min(255, Math.round(lum[k] * 255)))]++;
  let lo = 0, hi = 255, acc = 0;
  while (lo < 255 && (acc += hist[lo]) < n * 0.01) lo++;
  acc = 0; while (hi > 0 && (acc += hist[hi]) < n * 0.01) hi--;
  return [lo, hi];
}

/**
 * Tune a grid in place.
 *   auto      stretch the 1st–99th percentile to 0–1 (a flat photo gets its blacks and whites back)
 *   range     [lo, hi] 0–255 to stretch with instead of measuring (video keeps it steady)
 *   contrast  1 = unchanged; >1 pushes tones apart around mid-grey
 *   brightness  −1…1 added after contrast
 *   gamma     <1 lifts the mid-tones (dither coverage is linear, so this is the mid-tone knob)
 *   sharpen   0…2: unsharp mask over one cell, which is what makes thin edges survive the dither
 *   invert    swap light and dark
 */
export function tune(lum, W, H, o = {}) {
  const n = W * H;
  if (o.auto !== false) {
    const [lo, hi] = o.range || levelsOf(lum);
    if (hi - lo > 8) for (let k = 0; k < n; k++) lum[k] = (lum[k] * 255 - lo) / (hi - lo);
  }
  const c = o.contrast ?? 1, b = o.brightness ?? 0, g = o.gamma ?? 1;
  if (c !== 1 || b !== 0 || g !== 1) for (let k = 0; k < n; k++) {
    let v = (lum[k] - 0.5) * c + 0.5 + b; v = v < 0 ? 0 : v > 1 ? 1 : v; lum[k] = g === 1 ? v : Math.pow(v, g);
  }
  if (o.sharpen > 0) {
    const src = Float32Array.from(lum), amt = o.sharpen;
    for (let j = 0; j < H; j++) for (let i = 0; i < W; i++) {
      let s = 0, m = 0;
      for (let dj = -1; dj <= 1; dj++) for (let di = -1; di <= 1; di++) { s += src[Math.max(0, Math.min(H - 1, j + dj)) * W + Math.max(0, Math.min(W - 1, i + di))]; m++; }
      const v = src[j * W + i] + amt * (src[j * W + i] - s / m); lum[j * W + i] = v < 0 ? 0 : v > 1 ? 1 : v;
    }
  }
  if (o.invert) for (let k = 0; k < n; k++) lum[k] = 1 - lum[k];
  return lum;
}

/** Order a grid into ink levels 0 … tones−1. `screen` is a name in SCREENS or an 8×8 table. */
export function dither(lum, W, H, o = {}) {
  const levels = Math.max(2, Math.min(16, Math.round(o.tones ?? 2)));
  const screen = typeof o.screen === "string" || o.screen == null ? SCREENS[o.screen || "bayer"] : o.screen;
  if (!screen) throw new Error(`Bitlight image: no screen called "${o.screen}"`);
  const out = o.out || new Uint8Array(W * H);
  // photographs have no depth, so no halo; the field never goes negative, so no misses
  ditherLevels(lum, null, W, H, out, W, 0, 0, 0, 0, screen, levels);
  return out;
}

/** Levels → RGBA bytes at `cell` pixels per dot. `colours` is ramp(unlit, lit, tones) or any [r,g,b][]. */
export function paint(levels, W, H, colours, cell = 1, out = new Uint8ClampedArray(W * cell * H * cell * 4)) {
  const stride = W * cell;
  for (let j = 0; j < H; j++) for (let i = 0; i < W; i++) {
    const c = colours[levels[j * W + i]];
    for (let y = 0; y < cell; y++) {
      let o = ((j * cell + y) * stride + i * cell) * 4;
      for (let x = 0; x < cell; x++, o += 4) { out[o] = c[0]; out[o + 1] = c[1]; out[o + 2] = c[2]; out[o + 3] = 255; }
    }
  }
  return out;
}

/** The whole pipeline for one picture. Returns { levels, W, H }. */
export function process(rgba, w, h, o = {}) {
  const cols = o.cols || Math.min(w, 240);
  const g = toGrid(lumaFromRGBA(rgba, w, h), w, h, cols);
  tune(g.lum, g.W, g.H, o);
  return { levels: dither(g.lum, g.W, g.H, o), W: g.W, H: g.H };
}

/*
 * Bitlight props — reusable pieces of geometry, shared by figures and films.
 *
 * Every prop is a plain signed-distance function in its own local frame
 * (base on y = 0 unless noted). Compose them with Math.min, move them by
 * offsetting the arguments, scale with f(x / s, y / s, z / s) * s.
 * `towerPart` tells a material function which part of the computer a surface
 * point belongs to, so figures (tone) and films (tone + glow) can dress it alike.
 */
import { sd } from "./core.js";

const { box, sphere, cylinder, capsule, smin } = sd;
const { abs, max, min, sqrt, sin, cos, atan2, PI } = Math;
const cylZ = (x, y, z, r, h) => cylinder(x, z, y, r, h); // axis along z
const norm = ([x, y, z]) => { const l = Math.hypot(x, y, z); return [x / l, y / l, z / l]; };

// ---------- the computer: one tower, two fans, side vents, a power light ----------
// local frame: base at y = 0, front face at z = +0.4
export function tower(x, y, z, fan) {
  const outer = box(x, y - 0.46, z, 0.2, 0.46, 0.4, 0.025);
  if (outer > 0.04) return outer;
  let d = outer;
  for (let i = 0; i < 4; i++) d = max(d, -box(x - 0.2, y - (0.56 + i * 0.09), z + 0.02, 0.03, 0.018, 0.25, 0.006));
  const sector = (2 * PI) / 7;
  for (let f = 0; f < 2; f++) {
    const ry = y - (f ? 0.29 : 0.63), rz = z - 0.4;
    d = max(d, -cylZ(x, ry, rz, 0.145, 0.05));
    const r = sqrt(x * x + ry * ry);
    if (r < 0.17 && rz > -0.08) {
      let th = atan2(ry, x) - fan * (f ? -1 : 1);
      th = (((th % sector) + sector) % sector) - sector / 2;
      const px = r * cos(th) - 0.085, py = r * sin(th) - 0.02 * (r - 0.03) / 0.1;
      const bx = abs(px) - 0.052, by = abs(py) - 0.014;
      const blade2 = sqrt(max(bx, 0) ** 2 + max(by, 0) ** 2) + min(max(bx, by), 0);
      const blade = max(blade2, abs(rz + 0.03) - 0.005);
      d = min(d, blade, cylZ(x, ry, rz + 0.03, 0.036, 0.012));
      // guard: two rings and a bar, proud of the face
      const ringA = Math.hypot(r - 0.142, rz - 0.004) - 0.007, ringB = Math.hypot(r - 0.08, rz - 0.004) - 0.005;
      const bar = max(abs(x) - 0.004, abs(rz - 0.004) - 0.004, r - 0.142);
      d = min(d, ringA, ringB, bar);
    }
  }
  return min(d, cylZ(x - 0.12, y - 0.86, z - 0.4, 0.022, 0.008));
}
// which part of the computer a surface point is on (local frame of tower())
export function towerPart(x, y, z) {
  if (z > 0.395 && Math.hypot(x - 0.12, y - 0.86) < 0.024) return "light";
  if (z < 0.355 && (Math.hypot(x, y - 0.63) < 0.146 || Math.hypot(x, y - 0.29) < 0.146)) return "well";
  if (z < 0.385 && (Math.hypot(x, y - 0.63) < 0.146 || Math.hypot(x, y - 0.29) < 0.146)) return "blade";
  return "body";
}

// ---------- a desk with a monitor, keyboard, mug, desk lamp and the computer ----------
export const LAMP_HEAD = [-0.58, 1.42, 0.78];
export const LAMP_DIR = norm([1.2, -0.45, -0.38]);
export const TX = 0.76, TY = 0.765; // the tower sits on the desk
// the desk itself: top and four legs
export function deskFrame(x, y, z) {
  let d = box(x, y - 0.74, z, 1.1, 0.025, 0.5, 0.01); // top
  for (const sx of [-1.03, 1.03]) for (const sz of [-0.43, 0.43]) d = min(d, box(x - sx, y - 0.36, z - sz, 0.03, 0.36, 0.03));
  return d;
}
// what stands on it: monitor, stand, keyboard, mug
export function deskGear(x, y, z) {
  const mx = x + 0.38;
  let d = box(mx, y - 1.2, z + 0.22, 0.45, 0.27, 0.02, 0.012); // monitor
  d = min(d, box(mx, y - 0.88, z + 0.25, 0.035, 0.13, 0.025), box(mx, y - 0.772, z + 0.22, 0.16, 0.007, 0.1, 0.005));
  d = min(d, box(mx, y - 0.782, z - 0.13, 0.34, 0.016, 0.11, 0.008)); // keyboard
  const mug = max(cylinder(x - 0.22, y - 0.86, z - 0.3, 0.065, 0.095, 0.01), -cylinder(x - 0.22, y - 0.89, z - 0.3, 0.052, 0.09));
  return min(d, mug);
}
// the desk lamp: base, two arms, and (when drawn) a shade around the bulb
export function deskLamp(x, y, z, withShade) {
  let d = cylinder(x + 0.95, y - 0.77, z - 0.3, 0.09, 0.012, 0.005);
  d = min(d, capsule(x, y, z, -0.95, 0.78, 0.3, -0.92, 1.38, 0.22, 0.014));
  d = min(d, capsule(x, y, z, -0.92, 1.38, 0.22, LAMP_HEAD[0], LAMP_HEAD[1], LAMP_HEAD[2], 0.014));
  if (withShade) {
    const qx = x - LAMP_HEAD[0], qy = y - LAMP_HEAD[1], qz = z - LAMP_HEAD[2];
    const shell = max(abs(sphere(qx, qy, qz, 0.1)) - 0.006, qx * LAMP_DIR[0] + qy * LAMP_DIR[1] + qz * LAMP_DIR[2] - 0.035);
    d = min(d, shell, sphere(qx - LAMP_DIR[0] * 0.03, qy - LAMP_DIR[1] * 0.03, qz - LAMP_DIR[2] * 0.03, 0.03));
  }
  return d;
}
// bounding boxes [cx, cy, cz, hx, hy, hz] around each group, for early-outs
export const DESK_BOUNDS = { frame: [0, 0.38, 0, 1.12, 0.4, 0.52], gear: [-0.27, 1.11, 0.05, 0.58, 0.37, 0.33], lamp: [-0.76, 1.14, 0.54, 0.29, 0.39, 0.35] };
export function deskObjects(x, y, z, withShade) {
  return min(deskFrame(x, y, z), deskGear(x, y, z), deskLamp(x, y, z, withShade), tower(x - TX, y - TY, z + 0.04, 0));
}
// ---------- server racks: rows facing +z, repeated along x ----------
export const P = 0.5, ROW = 1.7;
// one rack, local frame centred on its footprint
export const rackUnit = (x, y, z) => box(x, y - 0.62, z, 0.22, 0.62, 0.3, 0.008);
export function rack(x, y, z) {
  const xi = Math.round(x / P), lx = x - xi * P;
  const zi = max(-6, min(0, Math.round(z / ROW))), lz = z - zi * ROW;
  return box(lx, y - 0.62, lz, 0.22, 0.62, 0.3, 0.008);
}
// ---------- a café table with a laptop, a cup and a plant ----------
export const HINGE_Y = 0.79, HINGE_Z = -0.12;
export function laptop(x, y, z, th) {
  let d = box(x - 0.05, y - 0.778, z - 0.1, 0.32, 0.012, 0.22, 0.008);
  const dy = sin(th), dz = cos(th), ny = cos(th), nz = -sin(th);
  const qy = y - HINGE_Y, qz = z - HINGE_Z;
  const along = qy * dy + qz * dz, nrm = qy * ny + qz * nz;
  return min(d, box(x - 0.05, along - 0.215, nrm - 0.008, 0.32, 0.215, 0.008, 0.006));
}
export function cafe(x, y, z, th) {
  let d = cylinder(x, y - 0.74, z, 0.95, 0.025, 0.01);
  d = min(d, cylinder(x, y - 0.37, z, 0.045, 0.37), cylinder(x, y - 0.015, z, 0.34, 0.015, 0.006));
  d = min(d, laptop(x, y, z, th));
  d = min(d, max(cylinder(x - 0.62, y - 0.85, z - 0.38, 0.06, 0.085, 0.01), -cylinder(x - 0.62, y - 0.88, z - 0.38, 0.048, 0.08)));
  // a small plant: pot and three leaves
  d = min(d, cylinder(x + 0.55, y - 0.82, z + 0.32, 0.085, 0.06, 0.01));
  const leaves = smin(smin(sphere(x + 0.55, y - 0.95, z + 0.32, 0.07), sphere(x + 0.5, y - 1.02, z + 0.36, 0.05), 0.06), sphere(x + 0.6, y - 1.0, z + 0.28, 0.05), 0.06);
  return min(d, leaves);
}
// ---------- a cloud bank (flat bottom at y = 0.16) ----------
// a flat-bottomed bank: a middle row of big puffs, smaller ones in front and behind
export const PUFFS = [[-0.8, 0.28, 0, 0.2], [-0.42, 0.34, 0.02, 0.27], [0, 0.38, 0, 0.32], [0.42, 0.34, -0.02, 0.27], [0.8, 0.28, 0, 0.2],
  [-0.55, 0.24, 0.3, 0.18], [-0.15, 0.26, 0.34, 0.2], [0.28, 0.25, 0.32, 0.19], [0.62, 0.22, 0.28, 0.16],
  [-0.5, 0.25, -0.3, 0.19], [0.15, 0.28, -0.32, 0.21], [0.55, 0.24, -0.28, 0.17]];
export function cloud(x, y, z) {
  let d = 9;
  for (const [px, py, pz, r] of PUFFS) d = smin(d, sphere(x - px, y - py, z - pz, r), 0.1);
  return max(d, 0.16 - y);
}

/*
 * Bitlight detail props — three objects built to be looked at closely.
 *
 * Detail at one bit is pixels per object, so these are modelled the way a
 * product shot is: knurled rings, engraved ticks, bevels, a textured grip,
 * moving parts. Each is { sdf(x, y, z, t), tone(x, y, z, t) } in its own frame
 * (base on y = 0, front toward +z). `tone` is the albedo 0–1; material detail
 * (leather grain, milled edges, glass coatings, a screen) lives there, in the
 * dither, instead of in geometry the grid cannot resolve. `t` is seconds and
 * only films pass it: a figure on a page is still (t = 0).
 */
import { sd } from "./core.js";

const { box, cylinder, capsule, rect, torus } = sd;
const { abs, max, min, sin, cos, atan2, floor, PI, hypot } = Math;
const hash = (a, b, c) => { const s = sin(a * 127.1 + b * 311.7 + c * 74.7) * 43758.5453; return s - floor(s); };
const cylZ = (x, y, z, r, h, e = 0) => cylinder(x, z, y, r, h, e); // axis along z
const ridge = (th, n) => 0.5 + 0.5 * cos(n * th);

// ---------- rangefinder camera ----------
const LY = 0.2; // lens axis height
export const rangefinder = {
  // turn: 0..1, the film-advance lever and the release button
  sdf(x, y, z, t = 0, turn = 0) {
    if (abs(x) > 0.7 || y > 0.5 || y < -0.01 || z > 0.62 || z < -0.2)
      return max(abs(x) - 0.6, y - 0.45, -y, abs(z - 0.2) - 0.45) + 0.05;
    let d = box(x, y - 0.2, z, 0.56, 0.17, 0.15, 0.035);                       // body
    d = max(d, -box(x + 0.36, y - 0.3, z - 0.15, 0.07, 0.04, 0.03, 0.012));   // finder window
    d = max(d, -box(x - 0.34, y - 0.3, z - 0.15, 0.045, 0.035, 0.03, 0.012)); // rangefinder window
    const r = hypot(x, y - LY);
    if (r < 0.3 && z > 0.1) {
      const th = atan2(y - LY, x);
      const grip = r - 0.012 * ridge(th, 56);                                  // knurled focus ring
      const ring = (rr, z0, z1, rv = r) => rect(rv - rr / 2, z - (z0 + z1) / 2, rr / 2, (z1 - z0) / 2);
      let l = ring(0.255, 0.12, 0.2);                                           // mount
      l = min(l, ring(0.2, 0.2, 0.3), ring(0.222, 0.3, 0.42, grip), ring(0.205, 0.42, 0.5), ring(0.19, 0.5, 0.56));
      l = max(l, -rect(r - 0.07, z - 0.56, 0.07, 0.07));                        // hollow front
      l = min(l, rect(r - 0.07, z - 0.505, 0.07, 0.012));                       // recessed glass
      d = min(d, l);
    }
    if (y > 0.3) {
      d = min(d, cylinder(x - 0.3, y - 0.375, z + 0.02, 0.085 - 0.012 * ridge(atan2(z + 0.02, x - 0.3), 36), 0.035, 0.006)); // shutter dial
      d = min(d, cylinder(x - 0.3, y - 0.42, z + 0.02, 0.04, 0.012, 0.005));
      d = min(d, cylinder(x - 0.14, y - 0.385, z + 0.02, 0.026, 0.02 - 0.01 * turn, 0.006));                                  // release
      d = min(d, cylinder(x + 0.36, y - 0.385, z + 0.02, 0.065 - 0.01 * ridge(atan2(z + 0.02, x + 0.36), 26), 0.03, 0.006)); // rewind knob
      d = min(d, box(x + 0.02, y - 0.372, z + 0.02, 0.1, 0.014, 0.025, 0.004));                                              // shoe
      d = min(d, capsule(x, y, z, 0.46, 0.376, -0.04 + 0.06 * turn, 0.5, 0.39, -0.09 + 0.1 * turn, 0.011));                  // advance lever
    }
    d = min(d, torus(y - 0.3, x - 0.6, z, 0.032, 0.008), torus(y - 0.3, x + 0.6, z, 0.032, 0.008)); // strap lugs
    return d;
  },
  tone(x, y, z) {
    const r = hypot(x, y - LY);
    if (z > 0.1 && r < 0.3) {
      const th = atan2(y - LY, x);
      if (z > 0.3 && z < 0.42 && r > 0.2) return ridge(th, 56) > 0.5 ? 0.97 : 0.5;                              // grip
      if (z > 0.42 && z < 0.5 && r > 0.19) return floor((th + PI) / (2 * PI) * 72) % 6 === 0 ? 0.2 : 0.88;      // engraved ticks
      if (z > 0.495 && r < 0.14) return r < 0.045 ? 0.04 : floor(r / 0.028) % 2 ? 0.12 : 0.34;                  // coated glass
      return 0.84;
    }
    if (z > 0.1 && y > 0.25 && ((x < -0.29 && x > -0.43) || (x > 0.29 && x < 0.39))) return 0.1;               // windows
    if (y < 0.33) return 0.14 + 0.24 * hash(floor(x * 55), floor(y * 55), floor(z * 55));                       // leatherette grain
    return 0.97;                                                                                                 // chrome top plate
  },
  bound: [0, 0.22, 0.2, 0.8],
};

// ---------- pocket watch (dial up, crown toward -z) ----------
const WR = 0.5;
export const pocketWatch = {
  sdf(x, y, z, t = 0) {
    if (hypot(x, z) > 0.75 || y > 0.2) return max(hypot(x, z) - 0.7, y - 0.15) + 0.05;
    const r = hypot(x, z), th = atan2(z, x);
    let d = cylinder(x, y - 0.06, z, WR, 0.06, 0.02);                           // case
    d = max(d, -cylinder(x, y - 0.1, z, WR - 0.07, 0.03));                      // well under the glass
    d = min(d, cylinder(x, y - 0.062, z, WR - 0.075, 0.034, 0.004));            // dial
    if (r > 0.34 && r < 0.43) {                                                 // twelve raised hour markers
      const a = (floor(((th + PI) / (2 * PI)) * 12 + 0.5) % 12 / 12) * 2 * PI - PI;
      d = min(d, box(r * sin(th - a), y - 0.1, r - 0.385, 0.012, 0.012, 0.03, 0.004));
    }
    const hand = (ang, len, w, h) => {
      const c = cos(ang), s = sin(ang), u = x * c + z * s, v = -x * s + z * c;
      return box(v, y - h, u - len / 2 + 0.03, w, 0.007, len / 2 + 0.03, 0.004);
    };
    d = min(d, hand(-PI / 2 + 0.55 + t * 0.02, 0.2, 0.014, 0.115), hand(-PI / 2 - 0.9 + t * 0.2, 0.3, 0.009, 0.125), hand(-PI / 2 + (t * 2 * PI) / 6, 0.34, 0.004, 0.135));
    d = min(d, cylinder(x, y - 0.13, z, 0.022, 0.018, 0.004));
    d = min(d, cylZ(x, y - 0.06, z + WR + 0.05, 0.05 - 0.008 * ridge(atan2(y - 0.06, x), 20), 0.05, 0.006)); // crown
    return min(d, torus(x, z + WR + 0.16, y - 0.06, 0.09, 0.016));                                           // bow
  },
  tone(x, y, z) {
    const r = hypot(x, z), th = atan2(z, x);
    if (y > 0.085 && r < WR - 0.075) {
      if (y > 0.108) return 0.05;                                               // hands and markers
      const tick = floor(((th + PI) / (2 * PI)) * 60 + 0.5);
      if (r > 0.4 && tick % 5 !== 0) return 0.2;                                // minute track
      return abs(r - 0.435) < 0.006 ? 0.3 : 0.95;
    }
    if (r > WR - 0.075 && r < WR - 0.02 && y > 0.08) return floor(((th + PI) / (2 * PI)) * 120) % 2 ? 0.95 : 0.5; // coin-edge bezel
    if (r > WR - 0.01) return floor(((th + PI) / (2 * PI)) * 90) % 2 ? 0.98 : 0.7;                                  // milled rim
    return 0.9;
  },
  bound: [0, 0.08, -0.1, 0.85],
};

// ---------- retro Mac: a bitmap face on the glass ----------
const SY = 0.67;
export const mac = {
  sdf(x, y, z) {
    if (abs(x) > 0.6 || y > 1.0 || abs(z) > 0.5) return max(abs(x) - 0.5, y - 0.95, abs(z) - 0.4) + 0.05;
    let d = box(x, y - 0.56, z, 0.34, 0.4, 0.32, 0.05);                           // case
    d = min(d, box(x, y - 0.95, z + 0.08, 0.27, 0.05, 0.2, 0.03));                // tapered top
    d = max(d, -box(x, y - SY, z - 0.32, 0.25, 0.23, 0.04, 0.025));               // bezel well
    d = min(d, box(x, y - SY, z - 0.285, 0.255, 0.235, 0.01));                    // glass
    d = max(d, -box(x - 0.1, y - 0.19, z - 0.31, 0.12, 0.011, 0.04, 0.006));      // floppy slot
    d = min(d, box(x, y - 0.025, z + 0.02, 0.38, 0.025, 0.34, 0.012));            // foot
    for (let i = 0; i < 5; i++) d = max(d, -box(x - 0.2 + i * -0.1, y - 0.995, z + 0.02, 0.015, 0.03, 0.12, 0.005)); // vents
    return d;
  },
  // the glass: lit pixels are paper, the rest ink; blinks every 2.6 s
  glow(x, y, z, t = 0) {
    if (!(z > 0.27 && abs(x) < 0.255 && abs(y - SY) < 0.235)) return 0;
    const u = x / 0.255, v = (y - SY) / 0.235;
    const gx = floor((u + 1) * 16) - 16, gy = floor((1 - (v + 1) / 2) * 16) - 8;
    const blink = t % 2.6 > 2.45;
    const eye = (cx) => abs(gx - cx) <= 1 && (blink ? gy === -2 : abs(gy + 2) <= 1);
    const mouth = gy >= 2 && gy <= 4 && ((gy === 4 && abs(gx) <= 3) || (gy === 3 && abs(gx) === 4) || (gy === 2 && abs(gx) === 5));
    return eye(-4) || eye(4) || mouth || abs(u) > 0.94 || abs(v) > 0.93 ? 1 : 0;
  },
  tone(x, y, z, t = 0) {
    if (z > 0.27 && abs(x) < 0.255 && abs(y - SY) < 0.235) return mac.glow(x, y, z, t) ? 0.97 : 0.03;
    if (z > 0.3 && y < 0.25 && y > 0.1) return abs(y - 0.19) < 0.012 ? 0.05 : 0.9;   // floppy slot
    if (z > 0.3 && y < 0.14) return 0.74;                                              // chin
    return 0.9;
  },
  bound: [0, 0.5, 0, 1.0],
};

/*
 * Bitlight — objects drawn in one bit, lit by your pointer.
 *
 * A figure is a still object on a plate, ray-marched once and cached. The
 * pointer is a lamp hovering over the plate; every frame re-lights the cached
 * surface (core.shade) and orders it into two inks (core.dither).
 *
 *   define({ name, means, sdf, bound, rest, albedo?, plateTone?, view?, read? })
 *     sdf(x, y, z)      signed distance to the object (the plate is added for you)
 *     bound             [x, y, z, r] sphere enclosing the object (shadow culling)
 *     rest              [x, y, z] lamp position at rest — this frame is the thumbnail
 *     albedo(x, y, z)   0–1 object tone (default 0.92); plateTone likewise (0.86)
 *     view              { half, lift, yaw, pitch, plate, cols, rows, lampY }
 *     read(lamp)        caption text; default "az 214° · el 38°"
 *   mount(host, figure | name, { cell, theme, ink, screen, light, label, onRead }) → handle
 *     ink     { lit, unlit }  the two colours (else --bitlight-lit / --bitlight-unlit)
 *     tones   number of inks, 2 (default) to 16, stepped from unlit to lit
 *     palette [css colours, darkest first] sets the inks (and their number) exactly
 *     screen  name in SCREENS: bayer (default) bayer4 dots lines diagonal noise
 *     light   { power, falloff, ambient, contrast, spot } the lamp; defaults are LOOK
 *
 * Do not edit this file or core.js to make one figure work. If a figure needs
 * something the kernel does not offer, the figure is the wrong shape.
 */
import { LOOK, BAYER, SCREENS, sd, shade, dither, ditherLevels, ramp, occlusion, normal, camera, march, lampAngles } from "./core.js";

export { LOOK, BAYER, SCREENS, sd };

const max = Math.max, min = Math.min, abs = Math.abs, sqrt = Math.sqrt;

// ---------- registry ----------
export const figures = new Map();
export function define(def) {
  for (const key of ["name", "means", "sdf", "bound", "rest"])
    if (def[key] == null) throw new Error(`Bitlight.define: "${key}" is required`);
  figures.set(def.name.toLowerCase(), def);
  return def;
}

// ---------- shared clock ----------
// One requestAnimationFrame for the whole page. Off-screen or settled figures
// leave `awake`, and the loop stops when `awake` is empty (rules · 09 Cost).
const awake = new Set();
let raf = 0, last = 0;
function wake(fig) {
  awake.add(fig);
  if (!raf) { last = performance.now(); raf = requestAnimationFrame(loop); }
}
function loop(now) {
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  for (const fig of awake) if (!fig.tick(dt)) awake.delete(fig);
  raf = awake.size ? requestAnimationFrame(loop) : 0;
}

const media = (q) => (typeof matchMedia === "function" ? matchMedia(q) : null);

function parseColor(str, fallback) {
  const probe = document.createElement("canvas").getContext("2d");
  probe.fillStyle = fallback;
  probe.fillStyle = (str || "").trim() || fallback;
  probe.fillRect(0, 0, 1, 1);
  const d = probe.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}

export const defaultRead = (L) => {
  const { az, el } = lampAngles([L.x, L.y, L.z]);
  return `az ${String(az).padStart(3, "0")}° · el ${el}°`;
};

// ---------- mount ----------
export function mount(host, figure, opts = {}) {
  const def = typeof figure === "string" ? figures.get(figure.toLowerCase()) : figure;
  if (!def) throw new Error(`Bitlight: no figure called "${figure}"`);
  const reduceMotion = media("(prefers-reduced-motion: reduce)");
  const prefersDark = media("(prefers-color-scheme: dark)");

  // live settings: ink / screen / light, changed with handle.set()
  const cfg = { ink: { ...opts.ink }, tones: 2, palette: null, screen: "bayer", light: { power: LOOK.POWER, falloff: LOOK.FALLOFF, ambient: LOOK.AMBIENT, contrast: LOOK.GAMMA, spot: false } };
  let screenMap = BAYER;
  function setScreen(name) {
    if (name == null) return;
    if (!SCREENS[name]) throw new Error(`Bitlight: no screen called "${name}" (${Object.keys(SCREENS).join(", ")})`);
    cfg.screen = name; screenMap = SCREENS[name];
  }
  setScreen(opts.screen);
  Object.assign(cfg.light, opts.light);
  if (opts.tones) cfg.tones = Math.max(2, Math.min(16, Math.round(opts.tones)));
  if (opts.palette && opts.palette.length > 1) cfg.palette = opts.palette.slice(0, 16);

  const view = Object.assign({ half: 2.3, lift: 0.35, yaw: 45, pitch: 30, plate: 1.6, cols: 160, rows: 120 }, def.view);
  const cell = opts.cell || 3;
  const W = view.cols, H = view.rows, N = W * H;
  const { f, r, u } = camera(view.yaw, view.pitch);
  const unit = (2 * view.half) / W;
  const cx = -f[0] * 12, cy = -f[1] * 12 + view.lift, cz = -f[2] * 12;

  const P = view.plate, PT = 0.08;
  const plate = (x, y, z) => sd.box(x, y + PT, z, P, PT, P, 0.06);
  const object = def.sdf;
  const scene = (x, y, z) => min(plate(x, y, z), object(x, y, z));
  const albedo = def.albedo || (() => 0.92);
  const plateTone = def.plateTone || (() => 0.86);

