// Pins — a 5×5 bed of pegs set in a diagonal wave. The lamp rakes across the field.
import { define, sd } from "../bitlight.js";

const { cylinder } = sd;
const S = 0.5, R = 0.14, N = 2, HMAX = 0.75;
const height = (i, j) => 0.12 + 0.6 * (0.5 + 0.5 * Math.cos((i - j) * 0.9));
